// Some portions generated by Claude Code

const test = require('node:test');
const assert = require('node:assert/strict');

const { createFormBrowserHarness } = require('./form-browser-harness.js');

function loadEditorSizing() {
    const harness = createFormBrowserHarness();
    harness.window.innerHeight = 900;
    const values = new Map();
    const storage = {
        values,
        getItem: (key) => values.has(key) ? values.get(key) : null,
        setItem: (key, value) => values.set(key, String(value)),
        removeItem: (key) => values.delete(key)
    };
    Object.defineProperty(harness.window, 'localStorage', { configurable: true, get: () => storage });
    harness.loadScripts(['yasqeHelper.js']);
    const wrapper = harness.registerElement('div', { className: 'CodeMirror' });
    // Without a fixed height the editor has its automatic (content) height of 160px.
    wrapper.getBoundingClientRect = () => ({ top: 0, left: 0, width: 600,
        height: wrapper.style.height ? parseFloat(wrapper.style.height) : 160 });
    const sizes = [];
    const cm = {
        getWrapperElement: () => wrapper,
        setSize(width, value) { sizes.push(value); wrapper.style.height = value + 'px'; },
        refresh() {}
    };
    const handle = harness.registerElement('div', { id: 'resize' });
    harness.context.workbench.editorSizing.install(cm, handle, 'rdf4j.workbench.editor-height.v1');
    return { handle, wrapper, sizes, storage };
}

// Review finding B29: a click on the resize handle must not fix (and remember) the editor height.
test('a click on the editor resize handle without a drag keeps the automatic height', () => {
    const { handle, wrapper, sizes, storage } = loadEditorSizing();
    handle.trigger('pointerdown', { button: 0, clientY: 100, pointerId: 1 });
    handle.trigger('pointermove', { clientY: 101 });
    handle.trigger('pointerup', { pointerId: 1 });
    assert.equal(storage.values.has('rdf4j.workbench.editor-height.v1'), false, 'nothing is remembered');
    assert.equal(wrapper.getAttribute('data-workbench-editor-height') ?? null, null, 'the editor still grows');
    assert.deepEqual(sizes, []);
});

test('a cancelled drag of the editor resize handle is not remembered and restores the height', () => {
    const { handle, wrapper, storage } = loadEditorSizing();
    handle.trigger('pointerdown', { button: 0, clientY: 100, pointerId: 1 });
    handle.trigger('pointermove', { clientY: 300 });
    assert.equal(wrapper.getAttribute('data-workbench-editor-height'), '360');
    handle.trigger('pointercancel', { pointerId: 1 });
    assert.equal(storage.values.has('rdf4j.workbench.editor-height.v1'), false, 'a cancelled drag is not remembered');
    assert.equal(wrapper.getAttribute('data-workbench-editor-height') ?? null, null, 'the automatic height returns');
    assert.equal(handle.getAttribute('data-dragging') ?? null, null);

    handle.trigger('pointerdown', { button: 0, clientY: 100, pointerId: 2 });
    handle.trigger('pointermove', { clientY: 200 });
    handle.trigger('pointerup', { pointerId: 2 });
    assert.equal(storage.values.get('rdf4j.workbench.editor-height.v1'), '260', 'a real drag is remembered');

    handle.trigger('pointerdown', { button: 0, clientY: 100, pointerId: 3 });
    handle.trigger('pointermove', { clientY: 400 });
    handle.trigger('pointercancel', { pointerId: 3 });
    assert.equal(wrapper.getAttribute('data-workbench-editor-height'), '260', 'the fixed height before the drag returns');
    assert.equal(storage.values.get('rdf4j.workbench.editor-height.v1'), '260');
});
